package com.tahamobiles.staff;

import android.app.Activity;
import android.net.ConnectivityManager;
import android.net.NetworkCapabilities;
import android.util.Base64;
import android.webkit.CookieManager;
import android.webkit.JavascriptInterface;
import android.webkit.WebView;
import org.json.JSONObject;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.net.HttpURLConnection;
import java.net.URI;
import java.net.URL;
import java.util.Iterator;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/** Bundled content only. Cookies are retained natively and never returned to JavaScript. */
final class ShopBridge {
    static final String LOCAL_ORIGIN="http://localhost";
    private final Activity activity;
    private final WebView web;
    private final ExecutorService workers=Executors.newFixedThreadPool(2);
    private volatile String shop;
    private long sessionEpoch;
    private volatile boolean closed;
    private final PendingPhotos photos;
    private final DeviceIdentity deviceIdentity;
    private final CompanionSecurity companion;
    private CounterDiscovery discovery;
    @JavascriptInterface public void discoverCounters(){activity.runOnUiThread(()->{if(discovery==null)discovery=new CounterDiscovery(activity,web);discovery.start();});}
    @JavascriptInterface public void stopDiscovery(){activity.runOnUiThread(()->{if(discovery!=null)discovery.stop();});}
    ShopBridge(Activity activity,WebView web){this.activity=activity;this.web=web;photos=new PendingPhotos(activity.getFilesDir());deviceIdentity=new DeviceIdentity(activity.getFilesDir());companion=new CompanionSecurity(activity);}
    @JavascriptInterface public synchronized String beginEnrollment(String qr){try{JSONObject pending=companion.begin(qr,deviceIdentity.getId(),DeviceIdentity.deviceName(android.os.Build.MANUFACTURER,android.os.Build.MODEL));if(!configure(pending.getString("shop")))throw new SecurityException();return pending.toString();}catch(Exception error){return "{}";}}
    @JavascriptInterface public String completeEnrollment(String id,String challenge){try{return companion.complete(id,challenge).toString();}catch(Exception error){return "{}";}}
    @JavascriptInterface public boolean companionSession(){return companion.active();}
    @JavascriptInterface public void scanQr(){activity.runOnUiThread(()->((MainActivity)activity).scanQr());}
    @JavascriptInterface public void openSettings(){activity.runOnUiThread(()->activity.startActivity(new android.content.Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+BuildConfig.APPLICATION_ID))));}
    @JavascriptInterface public boolean saveCapture(String record){return record.length()<12*1024*1024&&shop!=null&&photos.save(record,shop);}
    @JavascriptInterface public String readCaptures(){return shop==null?"[]":photos.read(shop);}
    @JavascriptInterface public void removeCapture(String id){photos.remove(id);activity.runOnUiThread(()->((MainActivity)activity).clearCaptureOriginal());}
    @JavascriptInterface public void clearPendingPhotos(){photos.clear();}
    @JavascriptInterface public void haptic(){try{android.os.Vibrator vibrator=(android.os.Vibrator)activity.getSystemService(android.content.Context.VIBRATOR_SERVICE);if(vibrator!=null&&vibrator.hasVibrator())vibrator.vibrate(android.os.VibrationEffect.createOneShot(35,android.os.VibrationEffect.DEFAULT_AMPLITUDE));}catch(Exception ignored){}}
    @JavascriptInterface public void clearPhotoOriginal(){activity.runOnUiThread(()->((MainActivity)activity).clearCaptureOriginal());}
    /** Only PDF bytes generated by the bundled receipt screen; never accepts a filesystem path or remote URL. */
    @JavascriptInterface public boolean shareReceiptPdf(String encoded){
        try{
            if(encoded==null||encoded.length()>12*1024*1024)return false;
            JSONObject request=new JSONObject(encoded);
            String filename=request.optString("filename","receipt.pdf").replaceAll("[^A-Za-z0-9._-]","_");
            if(!filename.endsWith(".pdf")||filename.length()>140)return false;
            byte[] bytes=Base64.decode(request.getString("base64"),Base64.DEFAULT);
            if(bytes.length<5||bytes.length>8*1024*1024||bytes[0]!='%'||bytes[1]!='P'||bytes[2]!='D'||bytes[3]!='F'||bytes[4]!='-')return false;
            java.io.File folder=new java.io.File(activity.getCacheDir(),"receipts");
            if(!folder.exists()&&!folder.mkdirs())return false;
            java.io.File[] previous=folder.listFiles();
            if(previous!=null)for(java.io.File old:previous)if(old.isFile()&&System.currentTimeMillis()-old.lastModified()>24*60*60*1000L)old.delete();
            java.io.File file=new java.io.File(folder,filename);
            try(java.io.FileOutputStream output=new java.io.FileOutputStream(file)){output.write(bytes);}
            android.net.Uri uri=androidx.core.content.FileProvider.getUriForFile(activity,BuildConfig.APPLICATION_ID+".receipts",file);
            android.content.Intent send=new android.content.Intent(android.content.Intent.ACTION_SEND);
            send.setType("application/pdf");send.putExtra(android.content.Intent.EXTRA_STREAM,uri);
            send.setClipData(android.content.ClipData.newRawUri("Receipt PDF",uri));
            send.addFlags(android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION);
            activity.runOnUiThread(()->{try{activity.startActivity(android.content.Intent.createChooser(send,"Share receipt PDF"));}catch(Exception ignored){android.widget.Toast.makeText(activity,"No app is available to share this PDF.",android.widget.Toast.LENGTH_LONG).show();}});
            return true;
        }catch(Exception error){return false;}
    }
    /** Opens only a validated WhatsApp destination. Opening the composer is never delivery confirmation. */
    @JavascriptInterface public boolean openWhatsapp(String encoded){
        try{
            if(encoded==null||encoded.length()>12000)return false;
            JSONObject data=new JSONObject(encoded);String number=data.getString("number");String message=data.getString("message");
            if(!number.matches("[1-9][0-9]{7,14}")||message.length()>8000)return false;
            android.net.Uri uri=new android.net.Uri.Builder().scheme("https").authority("wa.me").appendPath(number).appendQueryParameter("text",message).build();
            activity.runOnUiThread(()->{try{activity.startActivity(new android.content.Intent(android.content.Intent.ACTION_VIEW,uri));}catch(Exception error){android.widget.Toast.makeText(activity,"Could not open WhatsApp. Copy the receipt link instead.",android.widget.Toast.LENGTH_LONG).show();}});return true;
        }catch(Exception error){return false;}
    }
    @JavascriptInterface public boolean saveToGallery(String data){if(android.os.Build.VERSION.SDK_INT<29)return false;android.net.Uri uri=null;try{if(data.length()>12*1024*1024||!data.matches("(?s)^data:image/(jpeg|png|webp);base64,[A-Za-z0-9+/=\\r\\n]+$"))return false;byte[] bytes=Base64.decode(data.substring(data.indexOf(',')+1),Base64.DEFAULT);String mime=data.substring(5,data.indexOf(';'));android.content.ContentValues values=new android.content.ContentValues();values.put(android.provider.MediaStore.Images.Media.DISPLAY_NAME,"Taha-"+System.currentTimeMillis()+"."+(mime.endsWith("png")?"png":mime.endsWith("webp")?"webp":"jpg"));values.put(android.provider.MediaStore.Images.Media.MIME_TYPE,mime);values.put(android.provider.MediaStore.Images.Media.RELATIVE_PATH,"Pictures/Taha Mobiles");values.put(android.provider.MediaStore.Images.Media.IS_PENDING,1);uri=activity.getContentResolver().insert(android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI,values);if(uri==null)return false;try(java.io.OutputStream output=activity.getContentResolver().openOutputStream(uri)){if(output==null)throw new java.io.IOException();output.write(bytes);}values.clear();values.put(android.provider.MediaStore.Images.Media.IS_PENDING,0);activity.getContentResolver().update(uri,values,null,null);return true;}catch(Exception ignored){if(uri!=null)activity.getContentResolver().delete(uri,null,null);return false;}}
    @JavascriptInterface public synchronized boolean configure(String address){
        String parsed=OriginPolicy.origin(address,BuildConfig.DEBUG);if(parsed==null)return false;
        companion.changeOrigin(parsed);
        String previous=activity.getPreferences(Activity.MODE_PRIVATE).getString("cookie-origin","");
        if(!parsed.equals(previous)){++sessionEpoch;CookieManager.getInstance().removeAllCookies(null);CookieManager.getInstance().flush();}
        activity.getPreferences(Activity.MODE_PRIVATE).edit().putString("cookie-origin",parsed).apply();shop=parsed;return true;
    }
    @JavascriptInterface public synchronized void clearSession(){++sessionEpoch;photos.clear();companion.clear();CookieManager.getInstance().removeAllCookies(null);CookieManager.getInstance().flush();}
    @JavascriptInterface public String info(){
        JSONObject result=new JSONObject();try{
            result.put("version",BuildConfig.VERSION_NAME);result.put("buildNumber",String.valueOf(BuildConfig.VERSION_CODE));result.put("build",BuildConfig.DEBUG?"TEST":"PRODUCTION");
            result.put("deviceId",deviceIdentity.getId());result.put("deviceName",DeviceIdentity.deviceName(android.os.Build.MANUFACTURER,android.os.Build.MODEL));
            result.put("cameraPermission",activity.checkSelfPermission(android.Manifest.permission.CAMERA)==android.content.pm.PackageManager.PERMISSION_GRANTED?"Granted":"Not granted · requested when needed");
            ConnectivityManager manager=(ConnectivityManager)activity.getSystemService(Activity.CONNECTIVITY_SERVICE);
            NetworkCapabilities capabilities=manager.getNetworkCapabilities(manager.getActiveNetwork());
            result.put("network",capabilities==null?"Offline":capabilities.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)?"Wi-Fi":capabilities.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR)?"Mobile":capabilities.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET)?"Ethernet":"Unknown");
        }catch(Exception ignored){}return result.toString();
    }
    @JavascriptInterface public void request(String encoded){
        if(encoded.length()>16*1024*1024)return;
        workers.execute(()->{
            JSONObject result=new JSONObject();HttpURLConnection connection=null;
            try{
                JSONObject request=new JSONObject(encoded);String id=request.getString("id");
                if(!id.matches("[0-9]{1,12}"))return;result.put("id",id);
                URI uri=new URI(request.getString("url"));
                boolean companionRefresh=companion.active()&&uri.getPath().equals("/api/v1/auth/refresh");
                if(companionRefresh)uri=new URI(companion.origin()+"/api/v1/auth/enrollment/refresh");
                String method=request.optString("method","GET");if(!method.matches("GET|POST|PUT|PATCH|DELETE"))throw new SecurityException();
                String requestOrigin;long requestEpoch;synchronized(this){requestOrigin=shop;requestEpoch=sessionEpoch;}
                boolean healthProbe=OriginPolicy.healthProbe(uri.toString(),method,BuildConfig.DEBUG);
                if(!healthProbe&&(requestOrigin==null||!OriginPolicy.sameOrigin(requestOrigin,uri.toString())||!uri.getPath().startsWith("/api/v1/")||uri.getPath().contains("..")||uri.getRawFragment()!=null))throw new SecurityException();
                if(companion.active()&&!"https".equals(uri.getScheme()))throw new SecurityException();
                connection=(HttpURLConnection)new URL(uri.toString()).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(8000);connection.setReadTimeout(15000);connection.setRequestMethod(method);
                if(connection instanceof javax.net.ssl.HttpsURLConnection&&OriginPolicy.sameOrigin(companion.origin(),uri.toString()))companion.protect((javax.net.ssl.HttpsURLConnection)connection);
                connection.setRequestProperty("Origin",LOCAL_ORIGIN);
                String cookie=healthProbe?null:CookieManager.getInstance().getCookie(uri.toString());if(cookie!=null)connection.setRequestProperty("Cookie",cookie);
                JSONObject headers=request.optJSONObject("headers");if(!healthProbe&&headers!=null)for(Iterator<String> keys=headers.keys();keys.hasNext();){String key=keys.next();if(key.equalsIgnoreCase("authorization")||key.equalsIgnoreCase("x-counter-session")||key.equalsIgnoreCase("content-type"))connection.setRequestProperty(key,headers.getString(key));}
                byte[] body=Base64.decode(request.optString("body",""),Base64.DEFAULT);if(body.length>10*1024*1024)throw new SecurityException();
                if(companionRefresh)body=companion.refresh().toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);
                if(healthProbe&&body.length>0)throw new SecurityException();
                if(body.length>0){connection.setDoOutput(true);connection.setFixedLengthStreamingMode(body.length);try(java.io.OutputStream output=connection.getOutputStream()){output.write(body);}}
                int status=connection.getResponseCode();result.put("status",status);
                synchronized(this){if(!healthProbe&&requestEpoch==sessionEpoch&&requestOrigin.equals(shop)){for(java.util.Map.Entry<String,java.util.List<String>> entry:connection.getHeaderFields().entrySet())if("set-cookie".equalsIgnoreCase(entry.getKey()))for(String value:entry.getValue())CookieManager.getInstance().setCookie(requestOrigin,value);CookieManager.getInstance().flush();}}
                String contentType=connection.getContentType();result.put("contentType",contentType==null?"application/json":contentType);
                InputStream input=status>=400?connection.getErrorStream():connection.getInputStream();ByteArrayOutputStream output=new ByteArrayOutputStream();
                if(input!=null)try(InputStream stream=input){byte[] bytes=new byte[8192];int read;while((read=stream.read(bytes))!=-1){if(output.size()+read>16*1024*1024)throw new SecurityException();output.write(bytes,0,read);}}
                byte[] responseBytes=output.toByteArray();
                if((companionRefresh||uri.getPath().matches("/api/v1/auth/enrollment/[a-f0-9-]{36}/complete"))&&status>=200&&status<300){
                    JSONObject enrolled=new JSONObject(new String(responseBytes,java.nio.charset.StandardCharsets.UTF_8));
                    synchronized(this){if(requestEpoch!=sessionEpoch||!requestOrigin.equals(shop))throw new SecurityException();companion.retain(enrolled.getString("refreshToken"));}
                    enrolled.remove("refreshToken");responseBytes=enrolled.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);
                }
                if(companionRefresh&&status==401)companion.clear();
                result.put("body",Base64.encodeToString(responseBytes,Base64.NO_WRAP));
            }catch(java.net.SocketTimeoutException error){putError(result,"TIMEOUT");}
            catch(SecurityException error){putError(result,"NETWORK_BLOCKED");}
            catch(Exception error){putError(result,"SHOP_NOT_REACHABLE");}
            finally{if(connection!=null)connection.disconnect();}
            String callback="window.__tahaNativeResponse&&window.__tahaNativeResponse("+result+")";
            activity.runOnUiThread(()->{if(!closed)web.evaluateJavascript(callback,null);});
        });
    }
    private void putError(JSONObject result,String error){try{result.put("error",error);}catch(Exception ignored){}}
    void close(){closed=true;if(discovery!=null)discovery.stop();workers.shutdownNow();}
}
